// ──────────────────────────────────────────────
// HMAC Signature Verification for Shopify Webhook
// ──────────────────────────────────────────────
const crypto = require('crypto');

const shopifySecret = $env.SHOPIFY_WEBHOOK_SECRET;
const hmacHeader = $input.first().headers['x-shopify-hmac-sha256'];
const rawBody = $input.first().rawBody;

if (!hmacHeader || !rawBody || !shopifySecret) {
  throw new Error('Missing HMAC header, raw body, or webhook secret');
}

const computedHmac = crypto
  .createHmac('sha256', shopifySecret)
  .update(rawBody, 'utf8')
  .digest('base64');

const isValid = crypto.timingSafeEqual(
  Buffer.from(hmacHeader),
  Buffer.from(computedHmac)
);

if (!isValid) {
  throw new Error('Invalid Shopify webhook HMAC signature - possible forgery');
}

return $input.all();

// ──────────────────────────────────────────────
// Fraud Detection: 5-Check Pipeline
// ──────────────────────────────────────────────
const order = $input.first().json;
const flags = [];
let severity = 'CLEAN';

// --- Check 1: Geo Mismatch ---
const billingCountry = order.billing_address?.country_code || '';
const shippingCountry = order.shipping_address?.country_code || '';
if (billingCountry && shippingCountry && billingCountry !== shippingCountry) {
  flags.push({ check: 'GEO_MISMATCH', severity: 'HIGH', detail: `Billing: ${billingCountry}, Shipping: ${shippingCountry}` });
}

// --- Check 2: Disposable Email ---
const email = (order.email || '').toLowerCase();
const emailDomain = email.split('@')[1] || '';

// Load disposable domains from workflow static data or fallback list
let disposableDomains = [];
try {
  const staticData = $getWorkflowStaticData('global');
  if (staticData.disposableDomains) {
    disposableDomains = staticData.disposableDomains;
  }
} catch(e) {
  // Fallback: top 50 most common disposable domains
  disposableDomains = [
    'mailinator.com','guerrillamail.com','tempmail.com','throwaway.email',
    'yopmail.com','sharklasers.com','guerrillamailblock.com','grr.la',
    'dispostable.com','maildrop.cc','temp-mail.org','fakeinbox.com',
    'trashmail.com','getnada.com','mohmal.com','emailondeck.com',
    'tempr.email','10minutemail.com','mailnesia.com','tmpmail.net'
  ];
}

if (disposableDomains.includes(emailDomain)) {
  flags.push({ check: 'DISPOSABLE_EMAIL', severity: 'HIGH', detail: `Domain: ${emailDomain}` });
}

// --- Check 3: High-Risk Shipping (PO Box / Freight Forwarder) ---
const addr1 = (order.shipping_address?.address1 || '').toLowerCase();
const addr2 = (order.shipping_address?.address2 || '').toLowerCase();
const fullAddr = `${addr1} ${addr2}`;

// PO Box detection
const poBoxRegex = /p\.?\s*o\.?\s*box\s*\d+|post\s*office\s*box/i;
if (poBoxRegex.test(fullAddr)) {
  flags.push({ check: 'PO_BOX', severity: 'MEDIUM', detail: `Address: ${fullAddr.trim()}` });
}

// Freight forwarder keyword detection
const forwarderKeywords = [
  'shipito', 'myus.com', 'planet express', 'stackry', 'borderlinx',
  'usgobuy', 'comgateway', 'shopusa', 'viabox', 'reship',
  'fishisfast', 'forward2me', 'parcl', 'opas.com', 'myusaddress'
];
const matchedForwarder = forwarderKeywords.find(kw => fullAddr.includes(kw));
if (matchedForwarder) {
  flags.push({ check: 'FREIGHT_FORWARDER', severity: 'MEDIUM', detail: `Matched: ${matchedForwarder}` });
}

// --- Determine overall severity ---
const hasHigh = flags.some(f => f.severity === 'HIGH');
const hasMedium = flags.some(f => f.severity === 'MEDIUM');
if (hasHigh) severity = 'HIGH';
else if (hasMedium) severity = 'MEDIUM';

return [{
  json: {
    ...order,
    _fraud: {
      flags,
      severity,
      flagCount: flags.length,
      checkedAt: new Date().toISOString()
    }
  }
}];

// ──────────────────────────────────────────────
// Velocity Check: Evaluate order frequency
// ──────────────────────────────────────────────
const order = $('Fraud Check (Local)').first().json;
const velocityResponse = $input.first().json;
const flags = [...order._fraud.flags];
let severity = order._fraud.severity;

// Count orders from same email in last 24h
const recentOrders = velocityResponse.orders || [];
if (recentOrders.length >= 3) {
  flags.push({
    check: 'VELOCITY_EMAIL',
    severity: 'HIGH',
    detail: `${recentOrders.length} orders from ${order.email} in 24h`
  });
  severity = 'HIGH';
}

// Check for same shipping address across recent orders
const currentAddrHash = JSON.stringify({
  a1: (order.shipping_address?.address1 || '').toLowerCase().trim(),
  zip: (order.shipping_address?.zip || '').trim()
});
const sameAddrCount = recentOrders.filter(o => {
  const h = JSON.stringify({
    a1: (o.shipping_address?.address1 || '').toLowerCase().trim(),
    zip: (o.shipping_address?.zip || '').trim()
  });
  return h === currentAddrHash;
}).length;

if (sameAddrCount >= 3) {
  flags.push({
    check: 'VELOCITY_ADDRESS',
    severity: 'HIGH',
    detail: `${sameAddrCount} orders to same address in 24h`
  });
  severity = 'HIGH';
}

return [{
  json: {
    ...order,
    _fraud: {
      flags,
      severity,
      flagCount: flags.length,
      checkedAt: order._fraud.checkedAt
    }
  }
}];

