// ──────────────────────────────────────────────
// Evaluate Lob Address Verification Result
// ──────────────────────────────────────────────
const order = $('Fraud Severity = MEDIUM?').first()?.json || $('Fraud Severity = HIGH?').first()?.json;
const lobResult = $input.first().json;

// If Lob call failed, fall back to regex validation
if (!lobResult || lobResult.error || !lobResult.deliverability) {
  // Fallback: basic regex checks
  const zip = order.shipping_address?.zip || '';
  const usZipRegex = /^\d{5}(-\d{4})?$/;
  const requiredFields = ['address1', 'city', 'province', 'zip', 'country'];
  const missingFields = requiredFields.filter(f => !order.shipping_address?.[f]);

  if (missingFields.length > 0) {
    return [{ json: { ...order, _address: { status: 'INVALID', method: 'regex_fallback', reason: `Missing fields: ${missingFields.join(', ')}` } } }];
  }
  if (order.shipping_address?.country_code === 'US' && !usZipRegex.test(zip)) {
    return [{ json: { ...order, _address: { status: 'INVALID', method: 'regex_fallback', reason: `Invalid US ZIP: ${zip}` } } }];
  }
  return [{ json: { ...order, _address: { status: 'VALID', method: 'regex_fallback', reason: 'Lob unavailable, regex passed' } } }];
}

// Evaluate Lob deliverability
const deliverability = lobResult.deliverability;
const undeliverable = deliverability === 'undeliverable';

// Use corrected address from Lob if deliverable
let correctedAddress = null;
if (!undeliverable && lobResult.primary_line) {
  correctedAddress = {
    address1: lobResult.primary_line,
    address2: lobResult.secondary_line || '',
    city: lobResult.components?.city || order.shipping_address?.city,
    state: lobResult.components?.state || order.shipping_address?.province_code,
    zip: lobResult.components?.zip_code ? `${lobResult.components.zip_code}-${lobResult.components.zip_code_plus_4 || ''}`.replace(/-$/, '') : order.shipping_address?.zip
  };
}

return [{
  json: {
    ...order,
    _address: {
      status: undeliverable ? 'UNDELIVERABLE' : 'VALID',
      method: 'lob_cass',
      deliverability,
      correctedAddress,
      lobId: lobResult.id
    }
  }
}];

