// ──────────────────────────────────────────────
// Map Shopify Order → ShipBob Order Payload
// ──────────────────────────────────────────────
const order = $input.first().json;
const addr = order._address?.correctedAddress || order.shipping_address;

const shipbobPayload = {
  shipping_method: 'Standard',
  recipient: {
    name: order.shipping_address?.name || `${order.shipping_address?.first_name || ''} ${order.shipping_address?.last_name || ''}`.trim(),
    address: {
      address1: addr.address1 || order.shipping_address?.address1,
      address2: addr.address2 || order.shipping_address?.address2 || '',
      city: addr.city || order.shipping_address?.city,
      state: addr.state || order.shipping_address?.province_code,
      country: order.shipping_address?.country_code || 'US',
      zip_code: addr.zip || order.shipping_address?.zip
    },
    email: order.email,
    phone_number: order.shipping_address?.phone || ''
  },
  products: (order.line_items || []).map(item => ({
    reference_id: item.sku || String(item.product_id),
    quantity: item.quantity,
    name: item.name
  })),
  reference_id: String(order.id),
  order_number: String(order.order_number),
  tags: [
    { name: 'shopify_order_id', value: String(order.id) },
    { name: 'source', value: 'n8n-automation' }
  ]
};

return [{ json: { _shipbobPayload: shipbobPayload, _originalOrder: order } }];

// Log success for audit trail
const shipbobResponse = $input.first().json;
return [{
  json: {
    status: 'SUCCESS',
    shipbob_order_id: shipbobResponse.id,
    shopify_order_id: shipbobResponse.reference_id,
    created_at: new Date().toISOString(),
    message: `Order successfully created in ShipBob with ID ${shipbobResponse.id}`
  }
}];

